// Sanitization guard: mask bearer tokens, nvapi keys, and secrets before posting
const errorData = $json.execution?.error || {};
let rawMsg = errorData.message || JSON.stringify(errorData);

// Redact Bearer tokens
rawMsg = rawMsg.replace(/Bearer\s+[a-zA-Z0-9_\-\.]+/gi, 'Bearer [REDACTED_TOKEN]');
// Redact NVAPI and OpenAI style keys
rawMsg = rawMsg.replace(/nvapi-[a-zA-Z0-9_\-]+/gi, 'nvapi-[REDACTED]');
rawMsg = rawMsg.replace(/sk-[a-zA-Z0-9_\-]+/gi, 'sk-[REDACTED]');
// Redact passwords
rawMsg = rawMsg.replace(/password[:=]\s*[^\s&,]+/gi, 'password=[REDACTED]');

return [{
  json: {
    workflow_name: $json.workflow?.name || 'Unknown Workflow',
    execution_id: $json.execution?.id || 'N/A',
    failed_node: errorData.node?.name || 'Unknown Node',
    sanitized_error: rawMsg,
    timestamp: new Date().toISOString()
  }
}];

